"use strict";const e=require("./request.js");exports.adminCheck=function(){return e.get("/admin/recipes/check")},exports.adminGetGenerationConfig=function(){return e.get("/admin/recipes/generation-config")},exports.adminRecipeDelete=function(n){return e.del(`/admin/recipes/${n}`)},exports.adminRecipeDetail=function(n){return e.get(`/admin/recipes/${n}`)},exports.adminRecipeGenImage=function(n){return e.post(`/admin/recipes/${n}/image`,{})},exports.adminRecipeList=function(n){return e.get("/admin/recipes",n)},exports.adminRecipeStats=function(){return e.get("/admin/recipes/stats")},exports.adminRecipeUpdate=function(n,i){return e.put(`/admin/recipes/${n}`,i)},exports.adminRunGenerationNow=function(n){return e.post("/admin/recipes/generation-run",{count:n})},exports.adminUpdateGenerationConfig=function(n){return e.put("/admin/recipes/generation-config",n)};
